// store/modules/chat.js
export const chatModule = {
  namespaced: true,
  state: {
    recentChats: [] // 最近聊天列表
  },
  mutations: {
    // 添加或更新最近聊天用户
    ADD_RECENT_CHAT(state, user) {
      // 检查用户是否已在列表中
      const existingIndex = state.recentChats.findIndex(item => item.id === user.id);
      if (existingIndex !== -1) {
        // 如果存在，移到列表顶部
        state.recentChats.splice(existingIndex, 1);
      }
      // 添加到列表顶部
      state.recentChats.unshift(user);
      // 限制列表长度，例如最多保存50个最近聊天
      if (state.recentChats.length > 50) {
        state.recentChats.pop();
      }
    },
    // 更新最近聊天（去重 + 置顶）
    UPDATE_RECENT_CHATS(state, user) {
      // 1. 查找是否已存在该用户
      const index = state.recentChats.findIndex(item => item.id === user.id);
      if (index !== -1) {
        // 存在则删除旧记录
        state.recentChats.splice(index, 1);
      }
      // 2. 插入到列表顶部（保证最新聊天在最前）
      state.recentChats.unshift({
        id: user.id,
        username: user.username,
        photo: user.photo,
      });
    },
    // 从数据库加载历史聊天后，初始化最近聊天（可选，避免重复）
    INIT_RECENT_CHATS(state, chats) {
      // 按 ID 去重，仅保留每个用户最后一条聊天
      const uniqueChats = Array.from(
        new Map(chats.map(item => [item.id, item])).values()
      );
      // 按时间倒序排序（最新在前）
      uniqueChats.sort((a, b) => new Date(b.time) - new Date(a.time));
      state.recentChats = uniqueChats;
    },
  },
  actions: {
    // 保存最近聊天列表到localStorage
    saveRecentChats({ state }) {
      localStorage.setItem('recentChats', JSON.stringify(state.recentChats));
    },
    // 对方发送消息时更新最近聊天列表（需要后端配合）
    updateRecentChatForReceiver({ commit }, user) {
      commit('ADD_RECENT_CHAT', user);
    }
  },
  getters: {
    getRecentChats: state => state.recentChats
  }
};

export default chatModule;
